body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    margin: 0;
    padding: 16px;
    background: #f7f8fa;
    color: #222;
}

h1 {
    font-size: 20px;
    margin: 0 0 12px 0;
}

h2 {
    font-size: 15px;
    margin: 0 0 8px 0;
    color: #444;
}

.container {
    display: flex;
    flex-direction: row;
    gap: 16px;
    align-items: stretch;
    width: 100%;
}

.panel {
    background: #fff;
    border: 1px solid #e3e5e8;
    border-radius: 6px;
    padding: 12px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.04);
}

#bubble-chart {
    flex: 1 1 60%;
    position: relative;
    min-width: 0;
}

#bubble-svg {
    width: 100%;
    height: 640px;
    display: block;
}

#table-panel {
    flex: 1 1 40%;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.table-wrapper {
    overflow-y: auto;
    max-height: 640px;
    border: 1px solid #e3e5e8;
    border-radius: 4px;
}

table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

thead th {
    position: sticky;
    top: 0;
    background: #f1f3f5;
    text-align: left;
    padding: 8px 10px;
    border-bottom: 1px solid #d6d9dc;
    font-weight: 600;
    z-index: 1;
}

tbody td {
    padding: 7px 10px;
    border-bottom: 1px solid #eef0f2;
}

tbody tr {
    cursor: pointer;
    transition: background 0.12s;
}

tbody tr:hover {
    background: #f5f8ff;
}

tbody tr.selected {
    background: #ffe9a8 !important;
}

.bubble {
    cursor: pointer;
    stroke: #fff;
    stroke-width: 1.2px;
    transition: stroke-width 0.12s;
}

.bubble.selected {
    stroke: #222;
    stroke-width: 3px;
}

.bubble-label {
    pointer-events: none;
    font-size: 10px;
    font-weight: 600;
    fill: #fff;
    text-anchor: middle;
    dominant-baseline: central;
    text-shadow: 0 1px 2px rgba(0,0,0,0.3);
}

.tooltip {
    position: absolute;
    pointer-events: none;
    background: rgba(30, 32, 36, 0.95);
    color: #fff;
    padding: 8px 10px;
    border-radius: 4px;
    font-size: 12px;
    line-height: 1.4;
    max-width: 260px;
    opacity: 0;
    transition: opacity 0.12s;
    z-index: 10;
}

.tooltip.visible {
    opacity: 1;
}

.tooltip .t-ticker {
    font-weight: 700;
    font-size: 13px;
    margin-bottom: 2px;
}

.legend {
    font-size: 12px;
}

.legend text {
    fill: #333;
}
