{"command": "create", "file_text": "// Stock portfolio visualization
// Inputs: data/stock-descriptions.csv (one row per stock), data/indiv-stock/*.csv (price history)
// Outputs: /root/output/index.html with a bubble chart (left) and a table (right)
// D3 version: v6 (local, loaded from js/d3.v6.min.js)

const SECTORS = ["Information Technology", "Industry", "Energy", "Financial", "ETF"];
const SECTOR_COLORS = {
    "Information Technology": "#4e79a7",
    "Industry": "#f28e2b",
    "Energy": "#59a14f",
    "Financial": "#e15759",
    "ETF": "#9c755f"
};
const ETF_RADIUS = 22;

function formatMarketCap(v) {
    if (v == null || isNaN(v) || v === "") return "";
    const n = +v;
    if (n >= 1e12) return (n / 1e12).toFixed(2) + "T";
    if (n >= 1e9)  return (n / 1e9).toFixed(2)  + "B";
    if (n >= 1e6)  return (n / 1e6).toFixed(2)  + "M";
    return d3.format(",")(n);
}

d3.csv("data/stock-descriptions.csv").then(raw => {
    const stocks = raw.map(d => ({
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector,
        marketCap: d.marketCap ? +d.marketCap : null,
        country: d.country || "",
        website: d.website || ""
    }));

    const svgEl = document.getElementById("bubble-svg");
    const width = svgEl.clientWidth;
    const height = svgEl.clientHeight;

    const marketCaps = stocks.filter(s => s.marketCap).map(s => s.marketCap);
    // sqrt scale -> area proportional to market cap
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(marketCaps), d3.max(marketCaps)])
        .range([14, 55]);

    stocks.forEach(s => {
        s.radius = s.sector === "ETF" ? ETF_RADIUS : radiusScale(s.marketCap);
    });

    // Sector cluster centers arranged in a tight 3x2 grid centered in the chart
    const presentSectors = SECTORS.filter(sec => stocks.some(s => s.sector === sec));
    const cols = Math.min(3, presentSectors.length);
    const rows = Math.ceil(presentSectors.length / cols);
    const padX = width * 0.18;
    const padY = height * 0.18;
    const innerW = width - 2 * padX;
    const innerH = height - 2 * padY;
    const stepX = cols > 1 ? innerW / (cols - 1) : 0;
    const stepY = rows > 1 ? innerH / (rows - 1) : 0;
    const sectorCenters = {};
    presentSectors.forEach((sec, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        sectorCenters[sec] = {
            x: padX + col * stepX,
            y: padY + row * stepY
        };
    });

    const svg = d3.select("#bubble-svg");
    const chartG = svg.append("g").attr("class", "chart");
    const legendG = svg.append("g").attr("class", "legend");

    // Legend (top-left)
    const legendItems = legendG.selectAll("g")
        .data(presentSectors)
        .join("g")
        .attr("transform", (_, i) => `translate(10, ${12 + i * 20})`);
    legendItems.append("rect")
        .attr("width", 14).attr("height", 14)
        .attr("rx", 2)
        .attr("fill", d => SECTOR_COLORS[d]);
    legendItems.append("text")
        .attr("x", 20).attr("y", 11)
        .text(d => d);

    // Bubbles
    const bubbleG = chartG.selectAll("g.node")
        .data(stocks, d => d.ticker)
        .join("g")
        .attr("class", "node")
        .style("cursor", "pointer");

    const circles = bubbleG.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => SECTOR_COLORS[d.sector]);

    bubbleG.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker);

    const tooltip = d3.select("#tooltip");

    bubbleG
        .on("mouseover", function(event, d) {
            if (d.sector === "ETF") return; // suppress tooltip for ETFs
            tooltip.classed("visible", true)
                .html(
                    `<div class="t-ticker">${d.ticker}</div>` +
                    `<div>${d.name}</div>` +
                    `<div>Sector: ${d.sector}</div>`
                );
        })
        .on("mousemove", function(event, d) {
            if (d.sector === "ETF") return;
            const container = document.getElementById("bubble-chart").getBoundingClientRect();
            tooltip
                .style("left", (event.clientX - container.left + 12) + "px")
                .style("top",  (event.clientY - container.top + 12) + "px");
        })
        .on("mouseout", function() {
            tooltip.classed("visible", false);
        })
        .on("click", function(event, d) {
            selectStock(d.ticker);
        });

    // Force simulation: cluster by sector
    const simulation = d3.forceSimulation(stocks)
        .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.18))
        .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.18))
        .force("charge", d3.forceManyBody().strength(-6))
        .force("collide", d3.forceCollide(d => d.radius + 1.5).iterations(3))
        .on("tick", () => {
            bubbleG.attr("transform", d => `translate(${d.x}, ${d.y})`);
        });

    // Table
    const tbody = d3.select("#stock-table tbody");
    const rowsSel = tbody.selectAll("tr")
        .data(stocks, d => d.ticker)
        .join("tr")
        .attr("data-ticker", d => d.ticker)
        .on("click", function(event, d) {
            selectStock(d.ticker);
        });

    rowsSel.append("td").text(d => d.ticker);
    rowsSel.append("td").text(d => d.name);
    rowsSel.append("td").text(d => d.sector);
    rowsSel.append("td").text(d => formatMarketCap(d.marketCap));

    // Selection linking the two views
    let selected = null;
    function selectStock(ticker) {
        selected = (selected === ticker) ? null : ticker;
        circles.classed("selected", d => d.ticker === selected);
        rowsSel.classed("selected", d => d.ticker === selected);
        if (selected) {
            const row = document.querySelector(`tr[data-ticker="${selected}"]`);
            if (row) row.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
    }
});
